<div class="ami-panel"><div class="ami-panel-body"><div class="d-flex justify-content-between align-items-center flex-wrap mb-3"><h2 class="ami-section-title m-0">Versi Standar SPMI</h2><?php if ($mutable): ?><a class="btn-ami btn-outline-ami" href="<?php echo site_url('lpmpi/spmi-standards/version/edit/' . (int) $version->id); ?>">Edit versi</a><?php endif; ?></div><p><strong><?php echo html_escape($version->version_code); ?></strong> — <?php echo html_escape($version->title); ?></p><p>Status: <span class="status-badge"><?php echo html_escape($version->status); ?></span></p><?php if (!empty($transitions)): ?><div class="ami-row-actions mb-3"><?php foreach ($transitions as $next_status): ?><?php echo form_open('lpmpi/spmi-standards/version/transition/' . (int) $version->id, ['class' => 'd-inline']); ?><input type="hidden" name="status" value="<?php echo html_escape($next_status); ?>"><button class="btn-ami btn-outline-ami" type="submit">Pindah ke <?php echo html_escape($next_status); ?></button><?php echo form_close(); ?><?php endforeach; ?></div><?php endif; ?><?php if (!$mutable): ?><div class="alert alert-info">Versi approved, active, dan retired bersifat hanya-baca.</div><?php endif; ?>
